  this.abK = "\u0415\u0451 \u0441\u0447\u0451\u0442 \u2014 \u0432 \u044d\u0442\u043e\u043c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438. \u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0430\u0439\u0442\u0435 \u043b\u044e\u0434\u0435\u0439 \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u0438\u0437 \u0440\u0430\u0437\u0434\u0435\u043b\u0430 \u00ab\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u00bb \u0438 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0447\u0451\u0442: \u00ab\u0421\u0447\u0435\u0442\u0430\u00bb, \u0437\u0430\u0442\u0435\u043c \u00ab\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0449\u0451\u00bb.";
  this.acj = "\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u044c";
  this.ack = "\u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u044d\u0442\u0443 \u0441\u0441\u044b\u043b\u043a\u0443 \u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u043e \u0445\u043e\u0442\u0438\u0442\u0435 \u0432\u0438\u0434\u0435\u0442\u044c \u0432 \u043e\u0431\u0449\u0438\u043d\u0435. \u041e\u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441\u0440\u0430\u0437\u0443 \u0432 \u044d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435.";
  this.abb = "\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0432\u0430\u0441";
  this.abB = "\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0435\u0449\u0451 \u0440\u0430\u0437";
  this.af3 = "\u0417\u0430\u0431\u044b\u0442\u044c \u044d\u0442\u0443 \u0437\u0430\u044f\u0432\u043a\u0443";
  this.ae7 = "\u041a\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u044c";
  this.ad2 = "\u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0436\u0434\u0451\u0442";
  this.ab4 = "\u041f\u0440\u0438\u043d\u044f\u0442\u044c";
  this.ae5 = "\u041e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c";
  this.ab6 = "\u041f\u0440\u0438\u043d\u044f\u0442";
  this.ae6 = "\u041e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u043e";
  this.adb = "\u041d\u0435 \u043f\u0440\u0438\u043d\u044f\u0442";
  this.adU = "\u042d\u0442\u043e \u043c\u0435\u0441\u0442\u043e \u0437\u0430\u043d\u044f\u0442\u043e: \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0435.";
  this.adS = "\u0412 \u043c\u0435\u0441\u0442\u0435 \u2014 \u043e\u0442 3 \u0434\u043e 40 \u0441\u0442\u0440\u043e\u0447\u043d\u044b\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u0438\u0445 \u0431\u0443\u043a\u0432, \u0446\u0438\u0444\u0440 \u0438\u043b\u0438 \u0434\u0435\u0444\u0438\u0441\u043e\u0432; \u0432 \u0435\u0434\u0438\u043d\u0438\u0446\u0435 \u2014 \u0431\u0443\u043a\u0432\u044b.";
  this.acf = "\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043e\u0442\u0441\u044e\u0434\u0430 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u043b\u044c\u0437\u044f \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.ace = "\u0417\u0434\u0435\u0441\u044c \u043e\u0431\u0449\u0438\u043d\u044b \u0441\u043e\u0437\u0434\u0430\u0451\u0442 \u043d\u0435 \u043a\u0430\u0436\u0434\u044b\u0439: \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u043a \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0443 \u044d\u0442\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0430.";
  this.ab9 = "\u0414\u0440\u0443\u0433\u0430\u044f \u043e\u0431\u0449\u0438\u043d\u0430";
  this.aeQ = "\u0415\u0434\u0438\u043d\u0438\u0446\u0430";
  this.adN = "\u0412 \u0434\u0440\u0443\u0433\u0443\u044e \u043e\u0431\u0449\u0438\u043d\u0443";
  this.af0 = "\u0412 \u043a\u0430\u043a\u0443\u044e \u043e\u0431\u0449\u0438\u043d\u0443";
  this.ad5 = "\u0412 \u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u044c.";
  this.aeJ = "\u041b\u0438\u043d\u0438\u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u044f";
  this.acB = "\u041b\u0438\u043d\u0438\u044f \u0434\u043e\u0432\u0435\u0440\u0438\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0440\u0443\u0433\u0430\u044f \u043e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0430\u0448\u0435\u0439. \u0422\u043e\u0433\u0434\u0430 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043c\u043e\u0433\u0443\u0442 \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0438 \u2014 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u041e\u041d\u0410 \u0434\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0435: \u0434\u043e\u043b\u0436\u043d\u044b \u043c\u044b; \u043c\u0438\u043d\u0443\u0441: \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c.";
  this.aeD = "\u041c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c";
  this.acY = "\u043b\u0438\u043d\u0438\u0439 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442";
  this.adF = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u043b\u0438\u043d\u0438\u044e";
  this.acv = "\u0410\u0434\u0440\u0435\u0441 \u0434\u0440\u0443\u0433\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.acw = "\u043a\u0430\u043a \u0432 \u0435\u0451 \u0441\u0441\u044b\u043b\u043a\u0435-\u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 ?node=";
  this.abz = "\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c";
  this.acy = "\u041b\u0438\u043d\u0438\u044f \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.acx = "\u041b\u0438\u043d\u0438\u044f \u043d\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.acA = "\u0422\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0432 \u0434\u0440\u0443\u0433\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u0435: \u043b\u0438\u043d\u0438\u0438 \u043c\u0435\u0436\u0434\u0443 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438 \u0435\u0449\u0451 \u043d\u0435 \u0441\u0434\u0435\u043b\u0430\u043d\u044b.";
  this.ad4 = "\u041f\u043e \u044d\u0442\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443 \u043e\u0431\u0449\u0438\u043d\u0430 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442.";
  this.acz = "\u042d\u0442\u043e \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u043e\u0431\u0449\u0438\u043d\u0430.";
  this.af1 = "\u041a\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u044c";
  this.abp = "\u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0435 (\u043f\u0440\u043e\u0449\u0435 \u0432\u0441\u0435\u0433\u043e)";
  this.adP = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u044f\u0442 (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f)";
  this.adO = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u0443 \u0432\u0441\u0435\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u044b\u0435 \u043b\u0438\u043d\u0438\u0438";
  this.adI = "\u0412\u0430\u0448 \u0441\u0447\u0451\u0442 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441 \u043d\u0443\u043b\u044f \u0438 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0438\u043b\u0438 \u0441\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u2014 \u0438 \u0442\u0440\u0430\u0442\u044c\u0442\u0435 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u043e\u0435.";
  this.acX = "\u0423 \u0441\u0447\u0451\u0442\u0430 \u0447\u0430\u0441\u0442\u043d\u043e\u0433\u043e \u043b\u0438\u0446\u0430 \u0432 \u044d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043d\u0435\u0442 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u0438\u0442\u044c.";
  this.aeb = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.aea = "\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442: \u0435\u0433\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u043d\u043e\u0432\u0438\u0447\u043e\u043a. \u041f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043d\u0430 \u043d\u0435\u0433\u043e \u043f\u043e\u043b\u0430\u0433\u0430\u0442\u044c\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u0435\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u0443.";
  this.aet = "1. \u041e\u0431\u0449\u0438\u043d\u0430 \u0432\u0435\u0434\u0451\u0442 \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443 \u0438 \u0431\u0435\u0440\u0443\u0442 \u0434\u0440\u0443\u0433 \u0443 \u0434\u0440\u0443\u0433\u0430. \u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u2014 \u043c\u0435\u0440\u0430 \u0432 \u044d\u0442\u043e\u043c \u0441\u0447\u0451\u0442\u0435; \u0432 \u0446\u0435\u043d\u0430\u0445 \u043e\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0434\u043d\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u0430 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u044b.\n2. \u0415\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u043d\u0435 \u0434\u0435\u043d\u044c\u0433\u0438. \u041d\u0438\u043a\u0442\u043e \u0438 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0451\u0442, \u043d\u0435 \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u0442 \u0438 \u043d\u0435 \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0438\u0445 \u043d\u0430 \u0434\u0435\u043d\u044c\u0433\u0438.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u044b\u0448\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0434\u0430\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0432\u0437\u044f\u043b; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043e\u043d \u0432\u0437\u044f\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0434\u0430\u043b, \u0438 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u0435 \u0441\u0432\u043e\u0438\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0438 \u0443\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u0435\u0441\u0442\u044c \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0438 \u043f\u043e\u0442\u043e\u043b\u043e\u043a; \u0438\u0445 \u0437\u0430\u0434\u0430\u0451\u0442 \u043e\u0431\u0449\u0438\u043d\u0430 \u0438 \u043c\u043e\u0436\u0435\u0442 \u043c\u0435\u043d\u044f\u0442\u044c.\n5. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u0431\u0449\u0438\u043d\u0430, \u0438 \u043e\u043d\u0430 \u0437\u043d\u0430\u0435\u0442 \u0438\u0445 \u043f\u043e \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u043c \u0438\u043c\u0435\u043d\u0430\u043c.\n6. \u041f\u0440\u043e\u0434\u0430\u0436\u0430 \u0437\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430. \u041a\u0430\u0436\u0434\u044b\u0439 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0447\u0435\u0442\u0430 \u0438 \u0441\u0430\u043c \u043f\u043b\u0430\u0442\u0438\u0442 \u043d\u0430\u043b\u043e\u0433\u0438, \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u043a\u0430\u043a \u0441 \u043b\u044e\u0431\u043e\u0439 \u043f\u0440\u043e\u0434\u0430\u0436\u0438.\n7. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u043c\u043e\u0436\u0435\u0442 \u0432\u044b\u0439\u0442\u0438 \u0432 \u043b\u044e\u0431\u043e\u0435 \u0432\u0440\u0435\u043c\u044f, \u043f\u0440\u0438\u0432\u0435\u0434\u044f \u0431\u0430\u043b\u0430\u043d\u0441 \u043a \u043d\u0443\u043b\u044e. \u0412\u044b\u0448\u0435\u0434\u0448\u0438\u0439 \u0441 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u0433\u0430\u0448\u0430\u0435\u0442 \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 30 \u0434\u043d\u0435\u0439.\n8. \u041e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0441\u0447\u0451\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u044d\u0442\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.aaM = "\u041f\u0440\u0438\u043d\u0438\u043c\u0430\u044e";
  this.ae8 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.aec = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u044b";
  this.ae9 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0438 \u043f\u0440\u0438\u043c\u0438\u0442\u0435 \u0438\u0445 \u0437\u0430\u043d\u043e\u0432\u043e.";
  this.adA = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0445.";
  this.abO = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.aeu = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043e";
  this.aev = "\u0412\u0430\u0448\u0438 \u0441\u0434\u0435\u043b\u043a\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0435 \u043e\u0431\u043c\u0435\u043d\u0430 \u0432 \u0432\u0438\u0434\u0435 CSV: \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0438\u0445 \u0432 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u0443. \u0421\u0434\u0435\u043b\u043a\u0430 \u0432 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u0445 \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430, \u043e\u043d\u0430 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438 \u043e\u0431\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043b\u043e\u0433\u043e\u043c \u043a\u0430\u043a \u043b\u044e\u0431\u0430\u044f \u0434\u0440\u0443\u0433\u0430\u044f.";
  this.ade = "\u042d\u0442\u043e\u0442 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c. \u0412\u044b\u0434\u0435\u043b\u0438\u0442\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438 \u0441\u043a\u043e\u043f\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443\u044e.";
  this.acC = "\u042f \u043f\u043e\u0442\u0435\u0440\u044f\u043b(\u0430) \u0441\u0432\u043e\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430";
  this.acD = "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u0447\u0451\u0442. \u042d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u043d\u043e\u0432\u044b\u0439 \u043a\u043b\u044e\u0447 \u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0448\u0443 \u043e\u0431\u0449\u0438\u043d\u0443 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c, \u0447\u0442\u043e \u044d\u0442\u043e \u0432\u044b. \u041f\u043e\u0441\u043b\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043a\u043b\u044e\u0447 \u043d\u0430\u0447\u043d\u0451\u0442 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0441\u0447\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0434\u0435\u043b\u044e \u2014 \u0432\u0440\u0435\u043c\u044f, \u0447\u0442\u043e\u0431\u044b \u0432\u044b \u0443\u0441\u043f\u0435\u043b\u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0441\u0438\u043b \u043a\u0442\u043e-\u0442\u043e \u0434\u0440\u0443\u0433\u043e\u0439.";
  this.acm = "\u042d\u0442\u043e \u043c\u043e\u0439 \u0441\u0447\u0451\u0442";
  this.abc = "\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ads = "\u0415\u0449\u0451 \u043d\u0435\u0442: \u043d\u0435\u0434\u0435\u043b\u044f \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u043d\u0435 \u043f\u0440\u043e\u0448\u043b\u0430.";
  this.abh = "\u041f\u0440\u0438\u043d\u044f\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ac3 = "\u0417\u0430\u0431\u044b\u0442\u044c";
  this.abx = "\u042d\u0442\u043e \u043d\u0435 \u044f: \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c";
  this.ae4 = "\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043e: \u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442.";
  this.ae2 = "\u041a\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ae1 = "\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0439\u0442\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0443\u0432\u0435\u0440\u0435\u043d\u044b, \u0447\u0442\u043e \u044d\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0441 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044e. \u0421\u0442\u0430\u0440\u044b\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u0441\u0447\u0451\u0442\u0430 \u0435\u0449\u0451 \u043d\u0435\u0434\u0435\u043b\u044e \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c.";
  this.ad1 = "\u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442";
  this.abM = "\u042d\u0442\u043e \u043e\u043d(\u0430): \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c";
  this.ae3 = "\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043e";
  this.abW = "\u041d\u0435 \u043e\u043d(\u0430): \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c";
  this.abj = "\u0414\u043e\u0441\u043a\u0430";
  this.abn = "\u0427\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e\u0442 \u0438 \u0447\u0442\u043e \u0438\u0449\u0443\u0442. \u0426\u0435\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u0435; \u0434\u043e\u043b\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u043a\u0430\u043a\u0430\u044f \u0435\u0451 \u0447\u0430\u0441\u0442\u044c \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, \u2014 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0441\u044f \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u0432\u043d\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b.";
  this.abm = "\u0412\u0438\u0434";
  this.adx = "\u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442";
  this.aeY = "\u0438\u0449\u0435\u0442";
  this.abk = "\u043f\u043e\u043a\u0430 \u043f\u0443\u0441\u0442\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0432\u044b\u043c";
  this.adE = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c";
  this.aaY = "\u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e";
  this.ab1 = "\u0418\u0449\u0443";
  this.abX = "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435";
  this.adW = "\u0426\u0435\u043d\u0430";
  this.adX = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
