  this.ag6 = "\u0407\u0457 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u2014 \u0443 \u0446\u044c\u043e\u043c\u0443 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443. \u0417\u0430\u043f\u0440\u043e\u0448\u0443\u0439\u0442\u0435 \u043b\u044e\u0434\u0435\u0439 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f\u043c \u0456\u0437 \u0440\u043e\u0437\u0434\u0456\u043b\u0443 \u00ab\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438\u00bb \u0439 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u00ab\u0420\u0430\u0445\u0443\u043d\u043a\u0438\u00bb, \u0434\u0430\u043b\u0456 \u00ab\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0430\u0431\u043e \u0434\u043e\u0434\u0430\u0442\u0438 \u0449\u0435\u00bb.";
  this.agF = "\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438";
  this.agG = "\u041d\u0430\u0434\u0456\u0448\u043b\u0456\u0442\u044c \u0446\u0435 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u043e \u0445\u043e\u0447\u0435\u0442\u0435 \u0431\u0430\u0447\u0438\u0442\u0438 \u0432 \u0433\u0440\u043e\u043c\u0430\u0434\u0456. \u0412\u043e\u043d\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0454 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u043e\u0434\u0440\u0430\u0437\u0443 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456.";
  this.afx = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0432\u0430\u0441";
  this.afX = "\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0449\u0435 \u0440\u0430\u0437";
  this.ajp = "\u0417\u0430\u0431\u0443\u0442\u0438 \u0446\u044e \u0437\u0430\u044f\u0432\u043a\u0443";
  this.ait = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.aho = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.afq = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.air = "\u0412\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.afs = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.ais = "\u0412\u0456\u0434\u0445\u0438\u043b\u0435\u043d\u043e";
  this.ahx = "\u041d\u0435 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.aig = "\u0426\u0435 \u043c\u0456\u0441\u0446\u0435 \u0437\u0430\u0439\u043d\u044f\u0442\u0435: \u043e\u0431\u0435\u0440\u0456\u0442\u044c \u0456\u043d\u0448\u0435.";
  this.aie = "\u0423 \u043c\u0456\u0441\u0446\u0456 \u2014 \u0432\u0456\u0434 3 \u0434\u043e 40 \u043c\u0430\u043b\u0438\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u044c\u043a\u0438\u0445 \u043b\u0456\u0442\u0435\u0440, \u0446\u0438\u0444\u0440 \u0430\u0431\u043e \u0434\u0435\u0444\u0456\u0441\u0456\u0432; \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043b\u0456\u0442\u0435\u0440\u0438.";
  this.agB = "\u0421\u044c\u043e\u0433\u043e\u0434\u043d\u0456 \u0437\u0432\u0456\u0434\u0441\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.agA = "\u0422\u0443\u0442 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u0435 \u043a\u043e\u0436\u0435\u043d: \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0446\u044c\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0443.";
  this.afv = "\u0406\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430";
  this.ajc = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f";
  this.ai9 = "\u0414\u043e \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.ajm = "\u0414\u043e \u044f\u043a\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.ahr = "\u0423 \u0442\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0456\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
  this.aj5 = "\u041b\u0456\u043d\u0456\u0457 \u0434\u043e\u0432\u0456\u0440\u0438";
  this.agX = "\u041b\u0456\u043d\u0456\u044f \u0434\u043e\u0432\u0456\u0440\u0438 \u043a\u0430\u0436\u0435, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0456\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043d\u0430\u0448\u0456\u0439. \u0422\u043e\u0434\u0456 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0456 \u2014 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0412\u041e\u041d\u0410 \u0434\u043e\u0432\u0456\u0440\u044f\u0454 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456: \u0432\u0438\u043d\u043d\u0456 \u043c\u0438; \u043c\u0456\u043d\u0443\u0441: \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c.";
  this.aiZ = "\u041c\u043e\u0436\u0443\u0442\u044c \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c";
  this.ahk = "\u043b\u0456\u043d\u0456\u0439 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0435\u043c\u0430\u0454";
  this.ai1 = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u043b\u0456\u043d\u0456\u044e";
  this.agR = "\u0410\u0434\u0440\u0435\u0441\u0430 \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.agS = "\u044f\u043a \u0443 \u0457\u0457 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u0456-\u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u0456 \u043f\u0456\u0441\u043b\u044f ?node=";
  this.afV = "\u0417\u043c\u0456\u043d\u0438\u0442\u0438";
  this.agU = "\u041b\u0456\u043d\u0456\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.agT = "\u041b\u0456\u043d\u0456\u044e \u043d\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.agW = "\u0422\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0440\u0430\u0445\u0443\u0454 \u0432 \u0456\u043d\u0448\u0456\u0439 \u043e\u0434\u0438\u043d\u0438\u0446\u0456: \u043b\u0456\u043d\u0456\u0457 \u043c\u0456\u0436 \u0440\u0456\u0437\u043d\u0438\u043c\u0438 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438 \u0449\u0435 \u043d\u0435 \u0437\u0440\u043e\u0431\u043b\u0435\u043d\u043e.";
  this.ahq = "\u0417\u0430 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454.";
  this.agV = "\u0426\u0435 \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430.";
  this.ajn = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u0438";
  this.afL = "\u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0456 (\u043d\u0430\u0439\u043f\u0440\u043e\u0441\u0442\u0456\u0448\u0435)";
  this.aib = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u044f\u043a\u0456 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e)";
  this.aia = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u0432 \u0443\u0441\u0456\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0456 \u043b\u0456\u043d\u0456\u0457";
  this.ai4 = "\u0412\u0430\u0448 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u043d\u0443\u043b\u044f \u0439 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0449\u043e\u0441\u044c \u0430\u0431\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0439\u0442\u0435 \u0440\u043e\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430 \u2014 \u0456 \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u0435\u043d\u0435.";
  this.ahj = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u0438\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0442\u0438.";
  this.aix = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aiw = "\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0442\u0435\u043a\u0441\u0442: \u0439\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043a\u043e\u0436\u0435\u043d \u043d\u043e\u0432\u0430\u0447\u043e\u043a. \u041f\u0435\u0440\u0448 \u043d\u0456\u0436 \u043d\u0430 \u043d\u044c\u043e\u0433\u043e \u043f\u043e\u043a\u043b\u0430\u0434\u0430\u0442\u0438\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0456\u0442\u044c \u0439\u043e\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u043e\u0432\u0456.";
  this.aiP = "1. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0435\u0434\u0435 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u043e\u0433\u043e, \u0449\u043e \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442\u044c \u043e\u0434\u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0439 \u0431\u0435\u0440\u0443\u0442\u044c \u043e\u0434\u043d\u0435 \u0432 \u043e\u0434\u043d\u043e\u0433\u043e. \u041e\u0434\u0438\u043d\u0438\u0446\u044f \u2014 \u043c\u0456\u0440\u0430 \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443; \u0443 \u0446\u0456\u043d\u0430\u0445 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u043e\u0434\u043d\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0457 \u0432\u0430\u043b\u044e\u0442\u0438.\n2. \u041e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043d\u0435 \u0433\u0440\u043e\u0448\u0456. \u041d\u0456\u0445\u0442\u043e \u0439 \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454, \u043d\u0435 \u043a\u0443\u043f\u0443\u0454 \u0456 \u043d\u0435 \u043e\u0431\u043c\u0456\u043d\u044e\u0454 \u0457\u0445 \u043d\u0430 \u0433\u0440\u043e\u0448\u0456.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u0438\u0449\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0434\u0430\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0443\u0437\u044f\u0432; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0432\u0456\u043d \u0443\u0437\u044f\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0434\u0430\u0432, \u0456 \u043c\u0430\u0454 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u0441\u0432\u043e\u0457\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0443 \u043b\u0456\u043d\u0456\u044e \u0456 \u0441\u0442\u0435\u043b\u044e; \u0457\u0445 \u0437\u0430\u0434\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0439 \u043c\u043e\u0436\u0435 \u0437\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438.\n5. \u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u0456 \u0432\u043e\u043d\u0430 \u0437\u043d\u0430\u0454 \u0457\u0445 \u0437\u0430 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c\u0438 \u0456\u043c\u0435\u043d\u0430\u043c\u0438.\n6. \u041f\u0440\u043e\u0434\u0430\u0436 \u0437\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u0438\u0441\u0442\u0430\u0432\u043b\u044f\u0454 \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439 \u0441\u0430\u043c \u0441\u043f\u043b\u0430\u0447\u0443\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u0438, \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u044f\u043a \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0443.\n7. \u0423\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u043e\u0436\u0435 \u0432\u0438\u0439\u0442\u0438 \u0431\u0443\u0434\u044c-\u043a\u043e\u043b\u0438, \u0437\u0432\u0456\u0432\u0448\u0438 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u043d\u0443\u043b\u044f. \u0422\u043e\u0439, \u0445\u0442\u043e \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u0437 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f, \u043f\u043e\u0433\u0430\u0448\u0430\u0454 \u0440\u0456\u0437\u043d\u0438\u0446\u044e \u0433\u0440\u043e\u0448\u0438\u043c\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 30 \u0434\u043d\u0456\u0432.\n8. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u043e\u0440\u0443\u0448\u0443\u0454 \u0446\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.af8 = "\u041f\u0440\u0438\u0439\u043c\u0430\u044e";
  this.aiu = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.aiy = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.aiv = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0437\u043c\u0456\u043d\u0438\u043b\u0438\u0441\u044f: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0456 \u043f\u0440\u0438\u0439\u043c\u0456\u0442\u044c \u0457\u0445 \u0437\u043d\u043e\u0432\u0443.";
  this.ahW = "\u0426\u044f \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0438\u0445.";
  this.aga = "\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u0432\u0438\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.aiQ = "\u0421\u043a\u043e\u043f\u0456\u0439\u043e\u0432\u0430\u043d\u043e";
  this.aiR = "\u0412\u0430\u0448\u0456 \u0443\u0433\u043e\u0434\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0456 \u043e\u0431\u043c\u0456\u043d\u0443 \u0443 \u0432\u0438\u0433\u043b\u044f\u0434\u0456 CSV: \u0432\u0441\u0442\u0430\u0432\u0442\u0435 \u0457\u0445 \u0443 \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0430\u0431\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u043e\u0432\u0456. \u0423\u0433\u043e\u0434\u0430 \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u0445 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436, \u0432\u0456\u043d \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0439 \u043e\u043f\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0456\u043d\u0448\u0438\u0439.";
  this.ahA = "\u0426\u0435\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0454 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438. \u0412\u0438\u0434\u0456\u043b\u0456\u0442\u044c \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0456 \u0441\u043a\u043e\u043f\u0456\u044e\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443.";
  this.agY = "\u042f \u0432\u0442\u0440\u0430\u0442\u0438\u0432(\u043b\u0430) \u0441\u0432\u043e\u0457 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457";
  this.agZ = "\u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a. \u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u043d\u043e\u0432\u0438\u0439 \u043a\u043b\u044e\u0447 \u0456 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0432\u0430\u0448\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438, \u0449\u043e \u0446\u0435 \u0432\u0438. \u041f\u0456\u0441\u043b\u044f \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u043a\u043b\u044e\u0447 \u0442\u0440\u0438\u043c\u0430\u0442\u0438\u043c\u0435 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0447\u0435\u0440\u0435\u0437 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u2014 \u0447\u0430\u0441, \u0449\u043e\u0431 \u0432\u0438 \u0432\u0441\u0442\u0438\u0433\u043b\u0438 \u0432\u0456\u0434\u043c\u043e\u0432\u0438\u0442\u0438, \u044f\u043a\u0449\u043e \u043f\u0440\u043e\u0441\u0438\u0432 \u0445\u0442\u043e\u0441\u044c \u0456\u043d\u0448\u0438\u0439.";
  this.agI = "\u0426\u0435 \u043c\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.afy = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ahO = "\u0429\u0435 \u043d\u0456: \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0435 \u043c\u0438\u043d\u0443\u0432.";
  this.afD = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.agp = "\u0417\u0430\u0431\u0443\u0442\u0438";
  this.afT = "\u0426\u0435 \u043d\u0435 \u044f: \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438";
  this.aiq = "\u0421\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e: \u0442\u043e\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0454.";
  this.aio = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ain = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0439\u0442\u0435, \u043b\u0438\u0448\u0435 \u044f\u043a\u0449\u043e \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0456, \u0449\u043e \u0446\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0456\u0442\u044c \u0456\u0437 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044e. \u0421\u0442\u0430\u0440\u0456 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u0449\u0435 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043c\u043e\u0436\u0443\u0442\u044c \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.";
  this.ahn = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u044c";
  this.ag8 = "\u0426\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438";
  this.aip = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043e";
  this.agi = "\u041d\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u0432\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.afF = "\u0414\u043e\u0448\u043a\u0430";
  this.afJ = "\u0429\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0456 \u0449\u043e \u0448\u0443\u043a\u0430\u044e\u0442\u044c. \u0426\u0456\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0456\u0439 \u0432\u0430\u043b\u044e\u0442\u0456; \u0447\u0430\u0441\u0442\u043a\u0430 \u043a\u0430\u0436\u0435, \u044f\u043a\u0430 \u0457\u0457 \u0447\u0430\u0441\u0442\u0438\u043d\u0430 \u0431\u0435\u0440\u0435\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043b\u0430\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u043f\u043e\u0437\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u044e.";
  this.afI = "\u0412\u0438\u0434";
  this.ahT = "\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454";
  this.ajk = "\u0448\u0443\u043a\u0430\u0454";
  this.afG = "\u043f\u043e\u043a\u0438 \u0449\u043e \u043f\u043e\u0440\u043e\u0436\u043d\u044c\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0448\u0438\u043c";
  this.ai0 = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438";
  this.afk = "\u041f\u0440\u043e\u043f\u043e\u043d\u0443\u044e";
  this.afn = "\u0428\u0443\u043a\u0430\u044e";
